// G6 (TODO): --mode=polar vs --mode=dungeon via push constant."},{"filePath":"c:\Users\eldno\chthonic-archive\vulkan-lab\cli-renderer\src\main.rs","oldString":"/// Walk cwd upward to find manifest/todo_roulette.json.","newString":"/// Record a VkImage layout transition barrier into `cmd`.
unsafe fn transition_image_layout(
