    float frac_y = fty - floor(fty);
    bool in_grid = (tx >= 0 && tx < TILE_COLS && ty >= 0 && ty < TILE_ROWS);

    if (in_grid) {
        // Find room at (tx, ty)
        int room_idx = -1;
