        (2,3),(4,3),(6,3),(8,3),
        (5,4),
    ];
    for (i, &(tx, ty)) in room_layout.iter().enumerate() {
        let task_idx = i.min(tasks.len().saturating_sub(1)) as u32;
        let phase = if i < tasks.len() { tasks[i].phase_angle } else { 0.0 };
        let rr = (0.5 + 0.5 * phase.cos()).clamp(0.0, 1.0);
        let rg = (0.5 + 0.5 * (phase + 2.0 * std::f32::consts::PI / 3.0).cos()).clamp(0.0, 1.0);
        let rb = (0.5 + 0.5 * (phase + 4.0 * std::f32::consts::PI / 3.0).cos()).clamp(0.0, 1.0);
        unsafe {
            ptr.add(i).write(IsoRoom {
                tile_x: tx, tile_y: ty,
                room_state: 0u32,
                task_idx,
                tag_color_r: rr, tag_color_g: rg, tag_color_b: rb,
                _pad: 0.0,
            });
