const [, , subcmd, ...rest] = process.argv;

switch (subcmd) {
  case "probe":
  case undefined:
    cmdProbe();
    break;
  case "info":
    cmdInfo();
    break;
  case "build":
    cmdBuild(rest);
    break;
  case "open":
    cmdOpen(rest);
    break;
  case "dashboard":
    cmdDashboard();
    break;
  default:
    console.error(`Unknown subcommand: ${subcmd}`);
    console.error("Available: probe | info | build | open | dashboard");
    process.exit(1);
}

