foreach ($districtName in @("CARIBBEAN_ARCHIPELAGO","SKYSKRAPEREN","RUSTBELTET","HAVSDOMINANSEN","NEKROKRONORIKET","VIRTUALITETSHELGEDOMMEN","FOYDALITETSDUALITETSLENKEN","SUPREME_MATRIARCH")) {
