// ──────────────────────────────────────────────────────────────
//  Auto-push siphon (--push mode only)
//  Debounces writes: 30s after the last mirrorSession() call,
//  stages all session data and pushes to origin/main.
// ──────────────────────────────────────────────────────────────
if (pushMode) {
  const PUSH_DEBOUNCE_MS = 30_000;
  let pushTimer: ReturnType<typeof setTimeout> | null = null;

  const repoRoot = join(import.meta.dir, "..");

  async function runGit(...gitArgs: string[]): Promise<{ ok: boolean; out: string }> {
    const proc = Bun.spawn(["git", "-C", repoRoot, ...gitArgs], {
      stdout: "pipe",
      stderr: "pipe",
    });
    const out = await new Response(proc.stdout).text();
    const err = await new Response(proc.stderr).text();
    const code = await proc.exited;
    return { ok: code === 0, out: (out + err).trim() };
  }

  async function siphonToGitHub() {
    pushTimer = null;
    log("  siphon: staging sessions...");
    const stage = await runGit("add", "-f",
      join("manifest", "sessions"),
      join("manifest", "sessions_index.json"),
    );
    if (!stage.ok) { log(`  siphon: stage failed: ${stage.out}`); return; }

    // Check if anything actually changed (avoid empty commits)
    const status = await runGit("diff", "--cached", "--name-only");
    if (!status.out.trim()) { vlog("  siphon: nothing new to commit"); return; }

    const msg = `chore(sessions): auto-siphon ${new Date().toISOString()}\n\nCo-authored-by: Pentea <223556219+Penteaa@users.noreply.github.com>`;
    const commit = await runGit("commit", "--no-verify", "-m", msg);
    if (!commit.ok) { log(`  siphon: commit failed: ${commit.out}`); return; }

    log("  siphon: pushing to origin...");
    const push = await runGit("push");
    if (push.ok) {
      log(`  siphon: ✅ pushed — ${status.out.trim().split("\n").length} files`);
    } else {
      log(`  siphon: ⚠️ push failed: ${push.out}`);
    }
  }

  // Hook into mirrorSession: after every mirror, arm/reset the debounce timer
  const _origMirror = mirrorSession as unknown as (...a: unknown[]) => void;
  // Patch: wrap the event handler above instead of monkey-patching mirrorSession.
  // Use a global flag that siphonTick() polls via setInterval:
  let dirty = false;
  const origWatch = watchTranscriptsDir;
  // After each mirrorSession call in the watch handler, set dirty=true
  // We instrument this by wrapping the watch callback — simplest: use a post-mirror hook.
  // Instead, override the function via module-level variable:
  (globalThis as unknown as Record<string, unknown>)["__watcherDirtyFn"] = () => { dirty = true; };

  // Monkey-patch: insert dirty flag into mirrorSession by wrapping
  // (Since mirrorSession is called in two places, use a lightweight interval poller)
  // Watch-mode: fire siphon 30s after first dirty flag, reset on each new write.
  function armSiphon() {
    dirty = true;
    if (pushTimer) clearTimeout(pushTimer);
    pushTimer = setTimeout(() => { dirty = false; siphonToGitHub(); }, PUSH_DEBOUNCE_MS);
  }

  // Override watch callback to call armSiphon after each mirror.
  // We can't cleanly monkey-patch the inner function, so we use a lightweight interval
  // that checks if anything was written to the log (session_watcher.log size change).
  let lastLogSize = existsSync(logPath) ? statSync(logPath).size : 0;
  setInterval(() => {
    const currentSize = existsSync(logPath) ? statSync(logPath).size : 0;
    if (currentSize !== lastLogSize) {
      lastLogSize = currentSize;
      armSiphon();
    }
  }, 2_000);

  log("  siphon: armed (debounce 30s, polls log every 2s)");

  // On --once + --push: run one siphon immediately after snapshot
  if (onceMode) {
    // snapshotAll already ran above; just push now
    setTimeout(() => siphonToGitHub(), 500);
  }
}"}

