  try { 
    $o = $_ | ConvertFrom-Json
    if ($o.type -eq "tool.execution_complete" -and $i -lt 2) { 
      $i++
      Write-Output "=== tool.execution_complete #$i ==="
      Write-Output $_
      Write-Output ""
    }
  } catch {} 
}

