Get-Content $t | ForEach-Object { 
  try { 
    $o = $_ | ConvertFrom-Json
    if ($o.type -match "result|response|return" -or ($o.data -and ($o.data | ConvertTo-Json) -match '"resultPreview"')) { 
      Write-Output "TYPE: $($o.type)"
      Write-Output ($_ | Select-Object -First 300)
      Write-Output ""
    }
  } catch {} 
} | Select-Object -First 50

### Step 4 — Check if assistant.message contains toolResults field
$found = 0
Get-Content $t | ForEach-Object {
  if ($found -ge 2) { return }
  try {
    $o = $_ | ConvertFrom-Json
    if ($o.type -eq "assistant.message" -and $o.data.toolResults) {
      Write-Output "=== assistant.message with toolResults ==="
      Write-Output ($_ | Select-Object -First 500)
      $found++
    }
  } catch {}
}

Report all output from all 4 steps."}

